  "opposition": "oppose の名詞。反対する動き、そして野党。",
  "optimistic": "ラテン語 optimus(最良の。optimal)。最良の側を見る構え。",
  "option": "ラテン語 optare(選ぶ。adopt, opt)。選べる道。",
